    "source": "gold-standard",
    "notes": "Topic mode — 7 cards covering semiconservative nature, key enzymes, directionality, leading/lagging strands, fidelity. Mixed front style."
  },
  "cards": [
    {
      "id": 1,
      "front": "DNA replication is semiconservative — meaning?",
      "back": "Each new double helix = one original strand + one new strand",
      "tags": [
        "mechanism"
      ]
    },
    {
      "id": 2,
      "front": "Helicase",
      "back": "Unwinds double helix at replication fork; breaks hydrogen bonds",
      "tags": [
        "enzyme"
      ]
    },
    {
      "id": 3,
      "front": "Why does replication need a primer?",
      "back": "DNA polymerase can only extend, not initiate — primase lays RNA primer first",
      "tags": [
        "enzyme",
        "mechanism"
      ]
    },
    {
      "id": 4,
      "front": "DNA polymerase direction: reads / synthesises",
      "back": "Reads 3'→5'; synthesises 5'→3' (antiparallel rule)",
      "tags": [
        "directionality"
      ]
    },
    {
      "id": 5,
      "front": "Leading vs lagging strand",
      "back": "Leading: continuous synthesis; lagging: Okazaki fragments synthesised away from fork",
      "tags": [
        "strands"
      ]
    },
    {
      "id": 6,
      "front": "DNA ligase",
      "back": "Seals nicks between Okazaki fragments; joins phosphodiester bonds",
      "tags": [
        "enzyme"
      ]
    },
    {
      "id": 7,
      "front": "Replication error rate",
      "back": "~1 error per 10⁹ bases; polymerase proofreads via 3'→5' exonuclease activity",
      "tags": [
        "fidelity"
      ]
    }
  ]
}

