  "cards": [
    {
      "id": 1,
      "front": "Arabic verb morphology system",
      "back": "Root (3 consonants) + vowel pattern = derived meaning — 10 standard forms (awzān)",
      "tags": [
        "system"
      ]
    },
    {
      "id": 2,
      "front": "Form I (فَعَلَ) — base form",
      "back": "No predictable semantic shift; meaning intrinsic to root: kataba=wrote, ʿalima=knew",
      "tags": [
        "form-I"
      ]
    },
    {
      "id": 3,
      "front": "Form II (فَعَّلَ) — doubled medial",
      "back": "Intensification, causative, or denominative: ʿalima→ʿallama (to teach)",
      "tags": [
        "form-II"
      ]
    },
    {
      "id": 4,
      "front": "Form III (فَاعَلَ) — long ā after C1",
      "back": "Reciprocal / mutual action with another: kātaba = to correspond with",
      "tags": [
        "form-III"
      ]
    },
    {
      "id": 5,
      "front": "Form IV (أَفْعَلَ) — prefix أ",
      "back": "Causative: aslama = to submit → Islam; arāda = to intend",
      "tags": [
        "form-IV"
      ]
    },
    {
      "id": 6,
      "front": "Form V (تَفَعَّلَ) — تَ + Form II",
      "back": "Reflexive of Form II; action for oneself: taʿallama = to learn",
      "tags": [
        "form-V"
      ]
    },
    {
      "id": 7,
      "front": "Form VI (تَفَاعَلَ) — تَ + Form III",
      "back": "Mutual reflexive between parties: taʿāwana = to cooperate",
      "tags": [
        "form-VI"
      ]
    },
    {
      "id": 8,
      "front": "Form VII (اِنْفَعَلَ) — prefix اِنْ",
      "back": "Intransitive / passive reflexive of I: inkasara = broke (no agent named)",
      "tags": [
        "form-VII"
      ]
    },
    {
      "id": 9,
      "front": "Form VIII (اِفْتَعَلَ) — infix تَ after C1",
      "back": "Reflexive variety: ijtamaʿa = gathered; ittaqā = was mindful of God",
      "tags": [
        "form-VIII"
      ]
    },
    {
      "id": 10,
      "front": "Form X (اِسْتَفْعَلَ) — prefix اِسْتَ",
      "back": "To seek / deem: istaghfara = sought forgiveness; istaʿmala = employed",
      "tags": [
        "form-X"
      ]
    }
  ]
}

