{
  "version": "1.0",
  "_meta": {
    "query": "classical conditioning",
    "source": "gold-standard",
    "notes": "Topic mode — 8 cards. Covers the full Pavlovian sequence: acquisition → extinction → recovery → generalisation/discrimination → higher-order. Terminology card uses the salivation paradigm as anchor."
  },
  "cards": [
    {
      "id": 1,
      "front": "Classical conditioning",
      "back": "Pairing neutral stimulus (NS) with unconditioned stimulus (US) → NS becomes conditioned stimulus (CS)",
      "tags": [
        "definition"
      ]
    },
    {
      "id": 2,
      "front": "US / UR / CS / CR",
      "back": "US (food)→UR (salivate); CS (bell)+US→CS alone→CR (salivate)",
      "tags": [
        "terminology"
      ]
    },
    {
      "id": 3,
      "front": "Acquisition",
      "back": "Phase of CS-US pairing; CR strengthens with repeated trials — optimal: CS slightly precedes US",
      "tags": [
        "process"
      ]
    },
    {
      "id": 4,
      "front": "Extinction",
      "back": "CS presented without US repeatedly → CR weakens and disappears",
      "tags": [
        "process"
      ]
    },
    {
      "id": 5,
      "front": "Spontaneous recovery",
      "back": "Extinguished CR reappears after a rest period — without retraining",
      "tags": [
        "process"
      ]
    },
    {
      "id": 6,
      "front": "Stimulus generalisation",
      "back": "CR elicited by stimuli similar to CS — response gradient: weaker as difference grows",
      "tags": [
        "generalisation"
      ]
    },
    {
      "id": 7,
      "front": "Stimulus discrimination",
      "back": "CS+ reinforced, CS− not → organism responds only to CS+; acquired via differential reinforcement",
      "tags": [
        "discrimination"
      ]
    },
    {
      "id": 8,
      "front": "Higher-order conditioning",
      "back": "Established CS₁ paired with new CS₂ → CS₂ elicits CR without ever being paired with US",
      "tags": [
        "higher-order"
      ]
    }
  ]
}

